  'intro.title': 'Zer da FontApp?',
  'intro.lead': 'Ur-iturrien azken egoera jakiteko sare kolaboratiboa. Handik pasatzen den bakoitzak abisa dezake iturria dariola, gutxi datorren edo lehor dagoen — hurrengoak jakin dezan desbideratu aurretik.',
  'intro.story': 'Ideia Pirinioetan sortu zen: hurbileneko iturrira kilometro batzuk desbideratu ondoren, guztiz lehor aurkitu nuen. Eta handik pasatako azkenak abisatu ahal izan balu?',
