  'gameHelp.title': 'How drops work',
  'gameHelp.intro': 'Drops are paid for new information about fountains, not for using the app. Opening it every day adds nothing; telling us something nobody knew does.',
  'gameHelp.whatPays': 'What pays, and how much',
  'gameHelp.basesNote': 'That is the starting figure. It is then multiplied by the circumstances.',
  'gameHelp.multipliers': 'Multipliers',
  'gameHelp.mult.desert': 'Desert (×{f}): the fountain is more than {km} km from any other already reviewed. Where there is no data is where it is needed most.',
  'gameHelp.mult.dry': 'Dry season (×{f}): checked in July or August, when it is likeliest to have run dry and matters most.',
  'gameHelp.mult.doubt': 'Doubtful (×{f}): someone reported a problem in the last 90 days and a second opinion is needed.',
  'gameHelp.mult.crowded': 'Crowded (×{f}): the fountain already has {n} recent reviews. One more from the same week adds little.',
  'gameHelp.maxNote': 'They stack, up to a ceiling of ×{m}.',
  'gameHelp.freshness': 'Returning to a forgotten fountain',
  'gameHelp.freshnessNote': 'Updating a fountain’s status pays according to how long nobody had been there. Checking what was checked yesterday adds nothing; checking what nobody has looked at in a year, a great deal.',
  'gameHelp.freshNever': 'Never reviewed',
  'gameHelp.freshFrom': 'From {n} days',
  'gameHelp.freshFirstWeek': 'The same week',
  'gameHelp.example': 'An example',
  'gameHelp.exampleText': 'You leave the first review of a remote fountain ({base} drops), it is far from everything (×{m1}) and it is August (×{m2}). That is {total} drops for a single stop.',
  'gameHelp.rules': 'Two more rules',
  'gameHelp.settle': 'Drops are confirmed {h} hours later, in case something has to be undone. Until then they show as “on the way”.',
