  'game.badgeAbout.international': 'For making settled contributions in different countries.',
  'game.badgeAbout.consistency': 'For contributing on distinct days: consistency matters more than one busy day.',
  'game.badgeAbout.reunion': 'For returning to a fountain after more than a year without updates.',
  'game.badgeAbout.teamwork': 'For contributing to other people’s fountains during their first thirty days.',
