  'gameHelp.basesNote': "C'est le chiffre de départ. Elle est ensuite multipliée par les circonstances.",
  'gameHelp.multipliers': "Multiplicateurs",
  'gameHelp.mult.desert': "Désert (×{f}) : la fontaine est à plus de {km} km de toute autre déjà examinée. Là où il n’y a pas de données, c’est là qu’elles sont le plus nécessaires.",
  'gameHelp.mult.dry': "Saison sèche (×{f}) : vérifiée en juillet ou en août, lorsqu'elle est la plus susceptible d'être à sec et qu'elle compte le plus.",
  'gameHelp.mult.doubt': "Douteux (×{f}) : quelqu’un a signalé un problème au cours des 90 derniers jours et un deuxième avis est nécessaire.",
  'gameHelp.mult.crowded': "Bondé (×{f}) : la fontaine a déjà des critiques récentes sur {n}. Un autre de la même semaine n’ajoute pas grand-chose.",
  'gameHelp.maxNote': "Ils s'empilent jusqu'à un plafond de ×{m}.",
  'gameHelp.freshness': "Retour à une fontaine oubliée",
  'gameHelp.freshnessNote': "La mise à jour du statut d’une fontaine est payante en fonction de la durée pendant laquelle personne n’y est resté. Vérifier ce qui a été vérifié hier n'ajoute rien ; vérifier ce que personne n’a regardé depuis un an, c’est beaucoup.",
  'gameHelp.freshNever': "Jamais révisé",
